package com.procurement.vendorquotation.controller;import com.procurement.common.response.*;import com.procurement.vendorquotation.dto.request.*;import com.procurement.vendorquotation.dto.response.*;import com.procurement.vendorquotation.entity.*;import com.procurement.vendorquotation.service.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/vendor-quotations")public class VendorQuotationController{private final VendorQuotationService service;public VendorQuotationController(VendorQuotationService s){service=s;}private Pageable p(int page,int size,String sort,String direction){return PageRequest.of(page,size,Sort.by(Sort.Direction.fromString(direction),sort));}@PostMapping public ResponseEntity<ApiResponse<VendorQuotationResponse>>create(@Valid@RequestBody VendorQuotationRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Vendor quotation created",service.create(r)));}@GetMapping public ApiResponse<PageResponse<VendorQuotationResponse>>search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long rfqId,@RequestParam(required=false)Long vendorId,@RequestParam(required=false)VendorQuotationStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return ApiResponse.success(service.search(keyword,rfqId,vendorId,status,p(page,size,sort,direction)));}@GetMapping("/search")public ApiResponse<PageResponse<VendorQuotationResponse>>searchAlias(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long rfqId,@RequestParam(required=false)Long vendorId,@RequestParam(required=false)VendorQuotationStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return search(keyword,rfqId,vendorId,status,page,size,sort,direction);}@GetMapping("/{id}")public ApiResponse<VendorQuotationResponse>get(@PathVariable Long id){return ApiResponse.success(service.get(id));}@PutMapping("/{id}")public ApiResponse<VendorQuotationResponse>update(@PathVariable Long id,@Valid@RequestBody VendorQuotationRequest r){return ApiResponse.success("Vendor quotation updated",service.update(id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void>delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}@PostMapping("/{id}/submit")public ApiResponse<VendorQuotationResponse>submit(@PathVariable Long id){return ApiResponse.success("Vendor quotation submitted",service.submit(id));}@PostMapping("/{id}/withdraw")public ApiResponse<VendorQuotationResponse>withdraw(@PathVariable Long id){return ApiResponse.success("Vendor quotation withdrawn",service.withdraw(id));}}
